    20	@Service
    21	public class OrderService implements OrderStateContext {
    22	    private final OrderRepository orderRepository;
    23	    private final OrderItemRepository orderItemRepository;
    24	    private final OrderPaymentRepository orderPaymentRepository;
    25	    private final ProductRepository productRepository;
